===== manifest.json =====
{
  "manifest_version": 3,
  "name": "Temu 店铺监测",
  "version": "0.2.6",
  "description": "监测 Temu 限流（严重/一般）+ 在售数量/点名上下架（A+B，与服务器赛狐互补），即时+定点汇总发飞书。",
  "permissions": [
    "storage",
    "alarms",
    "tabs",
    "idle"
  ],
  "host_permissions": [
    "https://agentseller.temu.com/*",
    "https://www.temu.com/*",
    "https://open.feishu.cn/*",
    "https://open.larksuite.com/*"
  ],
  "background": {
    "service_worker": "background.js"
  },
  "action": {
    "default_popup": "popup.html",
    "default_title": "Temu 店铺监测"
  },
  "options_page": "options.html",
  "content_scripts": [
    {
      "matches": [
        "https://agentseller.temu.com/*"
      ],
      "js": [
        "logger.js",
        "content.js"
      ],
      "run_at": "document_start"
    },
    {
      "matches": [
        "https://www.temu.com/*"
      ],
      "js": [
        "logger.js",
        "content-front.js"
      ],
      "run_at": "document_idle"
    }
  ],
  "web_accessible_resources": [
    {
      "resources": [
        "inject.js"
      ],
      "matches": [
        "https://agentseller.temu.com/*"
      ]
    }
  ]
}


===== 使用说明.txt =====
Temu 店铺监测插件 · 使用说明（v19 上下架 A+B）
========================================

【分工】
  本插件（装在你日常 Chrome）负责：
    · 在售商品限流监测 + 严重/一般分级
    · 即时飞书告警（新限流 / 等级升级）
    · 每天 09:30 / 16:30 定点汇总（有差异才列差异）
    · 可选：写入飞书多维表格 + 严重限流建飞书任务
    · 多店空闲轮巡
    · 【v19】在售上下架 A+B（Temu 后台为准，补赛狐同步滞后）
        A 数量：countStatus 在售 N 变化 → 即时飞书（数量卡）
        B 点名：扫「在售中」清单
          - 下架：上轮有、这轮没有 → 点名 + 编辑链接（立即）
          - 上架：新进先记 pending，连续两轮仍在售才点名（防抖动）
        与服务器赛狐可能双报：同一 productId 插件侧 6 小时冷却；
        卡片带「插件·后台」字样，便于和赛狐卡区分。

  公司服务器赛狐仍跑上下架（selectStatus=12）。
  赛狐慢/漏时，以本插件后台扫描为准先报。


一、限流等级
-----------
  前提：商品【在售】且有限流信号（流量待关注 或 近期有下降）

  🔴 严重限流（满足任一）
    · SKU 货号以 VIP 开头 → 自有商品
    · SKU 货号以 JM 开头，且带「热销款」标签 → 黑猫渠道

  🟠 一般限流
    · 有限流，但不满足严重条件

  ❌ 已下架 / 已终止商品即使显示限流徽标 → 不报
  ❌ 同一商品 6 小时内不重复即时推（等级升级为严重除外）
  ❌ 切换店铺不会把已有限流再推一遍（v18：chip 未升高只静默记入）


二、上下架 A+B 时机
-----------------
  · 当前店：页面一返回 countStatus，数量有变 → 立刻数量卡；
    约 6 秒后若仍停留在该店 → 自动扫在售清单点名
  · 其它店：约每 15 分钟闹钟 + 电脑空闲/锁屏 ≥ 4 分钟 → 轮巡切店并扫描
  · 手动：popup「轮巡所有店」立刻扫
  · 升级后每店第一轮只建基准，不告警（避免历史库存误报）


三、安装
------
1. chrome://extensions → 开发者模式 → 加载已解压（本文件夹）
2. 从旧版升级：扩展开关【关掉再打开】（必须，否则仍是旧 SW）
3. popup 顶部应显示：后台：v19-上下架A+B


四、配置
------
1. 飞书群机器人 Webhook → 设置页粘贴 → 测试飞书
2. （可选）多维表 / 任务：
   · 企业自建应用 App ID / App Secret
   · 多维表格 app_token + table_id
   · 勾选「严重限流时创建飞书任务」
   · 应用权限：bitable 读写、task 创建；把应用加为表格协作者
3. 必提醒默认 09:30、16:30（可改）


五、日常
------
1. 保持登录，留一个 https://agentseller.temu.com/goods/list 标签
2. 新限流会即时推红/橙卡；定点时推差异汇总
3. 在售数量变化推数量卡；点名卡带商品链接
4. 电脑空闲约 4 分钟会轮巡各店（流量 + 在售清单）
5. 手动切店：限流仍按 v18 静默吸收规则


六、多维表建议字段
----------------
  店铺 | 商品名 | productId | SKC | SKU货号
  限流类型（待关注/近期下降/两者）
  严重等级（严重/一般）| 热销款 | 编辑链接
  最近推送时间 | 判定原因


七、常见问题
----------
· popup 非 v19-上下架A+B：关开插件开关
· 切店还在刷旧限流：确认已是 v18+ 静默规则；关开一次
· 刚升级就报一堆下架：不应发生（首轮只建基）。若发生请导出日志
· 下架数量卡有了但没有点名：当时不在该店页面 → 等空闲轮巡或点「轮巡所有店」
· 上架要等两轮轮巡才报：有意设计（二次确认），防扫表抖动
· 和赛狐各报一次：同一商品 6h 内插件不重复点名；赛狐侧仍可能再推
· 多维表没写入：检查 app 权限、协作者、字段名
· 严重判成一般：确认列表能看到 SKU货号列与「热销款」


说明：凭证与业务数据只存本机；告警发到你配置的 Webhook / 多维表。


===== content.js =====
// 隔离世界：① 注入 inject.js；② 转发接口响应(带当前店名)；③ 读流量待关注 chip；
// ④ 接收后台指令自动切店(轮巡用)。
(function () {
  var LOG = TemuLogger.createLogger('content');
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  LOG.info('content.js loaded -- v19');

  // 页面操作互斥锁：scanWatchList/scanOnSaleList/switchTo 都会改动「快速筛选/tab/切店」状态，
  // 绝不能并发——否则「商品流量待关注」筛选一打开，并发的在售扫描就只扫到筛选后的几条，
  // 误判成「下架 N 个」（这是历史假告警「在售 13→3」的根因）。所有改动型指令排队串行执行。
  let opChain = Promise.resolve();
  function withLock(fn) {
    const run = opChain.then(fn, fn); // 无论上一个成功/失败都接着跑（fn 不依赖上个结果）
    opChain = run.then(() => {}, (e) => { LOG.warn('Locked operation failed: ' + (e && e.message || e)); }); // 吞掉结果/异常，保持链条连续
    return run; // 调用方拿到 fn 的真实结果/异常
  }

  // 注入 MAIN world hook
  try {
    const s = document.createElement('script');
    s.src = chrome.runtime.getURL('inject.js');
    s.onload = () => s.remove();
    (document.head || document.documentElement).appendChild(s);
    LOG.info('inject.js injected into MAIN world');
  } catch (e) { LOG.warn('inject.js injection failed: ' + (e && e.message || e)); }

  // ---------- 读当前店铺名（右上角英文店名） ----------
  // 假店名黑名单：商品颜色/规格/尺码常被误读成「店名」写进 storage
  // （历史假店：Beige/Black/Charcoal/Grey/Rustic Brown/White Grey/Black Grey…）
  const FAKE_STORE_WORDS = /^(black|white|grey|gray|beige|brown|charcoal|red|blue|green|pink|purple|yellow|orange|gold|silver|ivory|cream|navy|olive|tan|khaki|maroon|coral|mint|teal|cyan|magenta|wine|rose|nude|camel|sand|stone|rustic|dark|light|natural|clear|multi|assorted|random|one size|os|xs|s|m|l|xl|xxl|xxxl|sku|skc|spu|usd|cny|eur|gbp|new|beta|seller|central|best|seller|english|chinese|all|more|less|edit|save|submit|cancel|close|next|prev|back|home|cart|account|login|sign|menu|search|help|support|local|warehouse|free|shipping|sale|off|pack|size|color|colour|style|qty|quantity|option|select)$/i;
  function isFakeStoreName(t) {
    if (!t) return true;
    const s = String(t).trim();
    if (s.length < 2 || s.length > 30) return true;
    // 纯大写+数字货号
    if (/^[A-Z0-9]+$/.test(s)) return true;
    // UI 固定词
    if (/^(Seller Central|Beta|NEW|SKC|SKU|USD|Best Seller)$/i.test(s)) return true;
    // 整句是颜色/规格词（含多词如 "Rustic Brown" / "Black Grey" / "Ivory White"）
    const words = s.split(/\s+/);
    if (words.every((w) => FAKE_STORE_WORDS.test(w))) return true;
    // 单色词（"Black"）
    if (words.length === 1 && FAKE_STORE_WORDS.test(words[0])) return true;
    return false;
  }
  function findStoreNameEl() {
    const W = window.innerWidth;
    let best = null;
    for (const el of document.querySelectorAll('span,a,div,button,p')) {
      const t = (el.textContent || '').trim();
      if (!/^[A-Za-z][A-Za-z0-9]*(?:\s[A-Za-z0-9]+){0,3}$/.test(t)) continue;
      if (isFakeStoreName(t)) continue;
      if (el.children.length > 2) continue;
      const r = el.getBoundingClientRect();
      if (r.width === 0 || r.top < 0 || r.top > 90) continue;
      if (r.left < W * 0.5) continue;
      if (!best || r.left > best.left) best = { el, left: r.left };
    }
    return best ? best.el : null;
  }
  function readStoreName() {
    const el = findStoreNameEl();
    if (!el) return null;
    const t = (el.textContent || '').trim();
    return isFakeStoreName(t) ? null : t;
  }

  // ---------- 转发接口响应 ----------
  window.addEventListener('message', (e) => {
    if (e.source !== window) return;
    const d = e.data;
    if (!d || d.__temuMon !== true) return;
    try { chrome.runtime.sendMessage({ type: 'capture', kind: d.kind, url: d.url, body: d.body, store: readStoreName() }); } catch (err) {}
  });

  // ---------- 读流量异常 ----------
  // ①「商品流量待关注」是常驻的快速筛选 chip，实测 DOM（勿凭空改）：
  //     <div class="use-quick-field_tsx_card__HASH"><span>商品流量待关注</span>
  //       <span class="use-quick-field_tsx_countDistance__HASH">4</span></div>
  //   计数在独立的 countDistance span 里（chip 常驻，N=0 也在，只有 N 变大才是真异常）。
  // ②「商品流量近期有下降」不是 chip，是逐行红色徽标（见 countDeclineBadges）。
  // 关键坑：行内徽标「商品流量待关注 ›」嵌在价格 TD 里 → 价格单元格文本也含该标签。
  //   旧的"全页捞文本+最短优先"靠排序巧合才没读到价格数字；
...[truncated]...

===== background.js =====
// Service worker：接收接口数据 → 按【店铺名】分别解析/对比/告警。
// 多店铺：同一账号下有多个店(HomeCove/Twilight Cove/Agnis)，切到哪个店就记哪个店，各自独立快照与告警。
// 数据只存本机 chrome.storage.local，不上传任何服务器。

importScripts('logger.js', 'feishuApp.js');
var log = TemuLogger.createLogger('bg');

// v14：流量为主；下架曾迁服务器赛狐。
// v15：流量只报在售 + 按 productId 冷却去重（下架商品也会挂限流徽标；切店不再刷屏）。
// v16：限流分级（严重 VIP / JM+热销；一般其它）+ 定点差异汇总 + 多维表/任务同步。
// v17：修切店重复告警——stores 读写全局串行，避免 updateStoreLatest 覆盖掉
//      snapshot.alertedTrafficIds；基线必须「非空已告警 ID」，空 {} / 仅 chip 计数不算基线。
// v18：切店时 chip 会短暂掉 0，snap.trafficWatch 被写成 0，恢复后 0→N 被当成「新增」全量推。
//      规则：snap 计数禁止被瞬时拉低；chip 未相对高水位上升时只静默吸收 ID，不发飞书；
//      另加全局 productId 冷却（跨店/快照丢失兜底）。
// v19：A+B 上下架（赛狐同步滞后时的后台兜底；卡片标注「插件·后台」）
//   A: countStatus 在售数升降 → 即时飞书（数量）+ 当前店立刻 scan 点名
//   B: 空闲/手动轮巡每店 scanOnSale → 下架点名；上架「连续两轮仍在售」才点名
//   productId 6h 冷却，降低与服务器赛狐双报刷屏（无法完全消除）
const ONSALE_MONITOR_IN_PLUGIN = true;
const ONSALE_QTY_ALERT = true;       // A：数量变化即时卡
const ONSALE_SCAN_ALERT = true;      // B：清单 diff 点名
const ONSALE_ID_COOLDOWN_MS = 6 * 60 * 60 * 1000;
const ONSALE_QTY_COOLDOWN_MS = 30 * 60 * 1000; // 同一店同 from→to 数量卡 30 分钟内不重复
const ONSALE_SCAN_DEBOUNCE_MS = 6000;

// 兼容旧名：曾用 DELIST_IN_PLUGIN 只控下架扫描
const DELIST_IN_PLUGIN = ONSALE_MONITOR_IN_PLUGIN && ONSALE_SCAN_ALERT;

const GOODS_URL = 'https://agentseller.temu.com/goods/list';
const DEFAULT_CONFIG = {
  webhook: '',
  intervalMinutes: 15,
  enabled: true,
  storeName: '',
  // 定时必提醒：每天固定时刻强制发飞书状态汇报（无异常也发，证明插件活着）
  mustRemindEnabled: true,
  mustRemindTimes: ['09:30', '16:30'],
  // 前台变体监测
  frontCheckEnabled: true,
  frontCheckIntervalHours: 3,
  // 飞书企业应用（多维表 + 任务）；本地填写，不进仓库
  feishuAppId: '',
  feishuAppSecret: '',
  bitableAppToken: '',
  bitableTableId: '',
  feishuTaskEnabled: true,
  feishuTasklistGuid: '',
};
const MUST_REMIND_PREFIX = 'mustRemind|';

// ---------------- 解析 ----------------
function parseCountStatus(body) {
  try {
    const j = JSON.parse(body);
    const list = j && j.result && j.result.skcTopStatusCountList;
    if (!Array.isArray(list)) return null;
    const pick = (s) => {
      const x = list.find((e) => e && e.skcTopStatus === s);
      return x && typeof x.skcTotal === 'number' ? x.skcTotal : null;
    };
    return { onSale: pick(100), unpublished: pick(0), removed: pick(200), deleted: pick(300) };
  } catch (e) { log.warn('parseCountStatus: failed to parse response'); return null; }
}
// 从 productSkuSpecList 拼规格名，如「颜色:Khaki / 数量:1pc」→「Khaki」优先单值，多维用「/」
function formatSkuSpecName(sku) {
  const specs = (sku && Array.isArray(sku.productSkuSpecList)) ? sku.productSkuSpecList : null;
  if (specs && specs.length) {
    return specs.map((sp) => String(sp.specName || sp.unitSpecName || '').trim()).filter(Boolean).join('/') || '';
  }
  return String((sku && (sku.specName || sku.skuName || sku.name)) || '').trim();
}
// 把单个 SKU 对象规范成统一结构
function normalizeSku(sku, product) {
  if (!sku || typeof sku !== 'object') return null;
  const skuId = sku.productSkuId || sku.skuId || sku.skuIdStr || sku.id || sku.skuSpecId || '';
  const name = formatSkuSpecName(sku);
  const extCode = String(sku.extCode || sku.skuExtCode || sku.outerSkuId || '').trim();
  if (!skuId && !name && !extCode) return null;
  return {
    skuId: skuId ? String(skuId) : '',
    name: name || extCode || ('SKU' + (skuId ? ' ' + skuId : '')),
    extCode: extCode,
    img: sku.thumbUrl || sku.skuImgUrl || sku.imageUrl || sku.imgUrl || '',
    productId: product && (product.productId || product.productIdStr) ? String(product.productId || product.productIdStr) : '',
    skc: product && (product.productSkcId || product.skcId) ? String(product.productSkcId || product.skcId) : '',
    productName: product && product.productName ? String(product.productName) : '',
    stock: typeof sku.realStock === 'number' ? sku.realStock
      : (typeof sku.virtualStock === 'number' ? sku.virtualStock : null),
  };
}
