325	}
326	function fmtNum(v) { return typeof v === 'number' ? String(v) : '—'; }
327	async function sendMustRemind(slot) {
328	  const cfg = await getConfig();
329	  if (!cfg.enabled || cfg.mustRemindEnabled === false) {
330	    log.info('MustRemind skipped: disabled');
331	    return { ok: false, msg: '未启用' };
332	  }
333	  if (!cfg.webhook) {
334	    log.warn('MustRemind skipped: no webhook');
335	    return { ok: false, msg: '未配置飞书 webhook' };
336	  }
337	  const stores = await getStores();
338	  const names = Object.keys(stores).sort();
339	  const lines = [
340	    '**定时必提醒' + (slot ? ' · ' + slot : '') + '**',
341	    '_存活汇报 + 限流差异（相对上一固定时点）_',
342	    '',
343	  ];
344	  const allDiffItems = []; // { store, item, change } change=added|upgraded|removed
345	  let anyDiff = false;
346	
347	  if (!names.length) {
348	    lines.push('_暂无店铺数据。请打开 goods/list 或点「轮巡所有店」。_');
349	  } else {
350	    for (const name of names) {
351	      const s = stores[name] || {};
352	      const L = s.latest || {};
353	      const snap = s.snapshot || {};
354	      const stale = L.ts && (Date.now() - L.ts > 2 * 60 * 60 * 1000);
355	      const pool = buildTrafficPool(L);
356	      const currMap = {};
357	      for (const it of pool) {
358	        currMap[String(it.productId)] = {
359	          severity: it.severity,
360	          name: it.name,
361	          skc: it.skc,
362	          skuCodes: it.skuCodes,
363	          hotSale: it.hotSale,
364	          kinds: it.kinds,
365	          reason: it.reason,
366	          productId: it.productId,
367	        };
368	      }
369	      const prevMap = snap.slotTrafficMap || {};
370	      const added = [];
371	      const upgraded = [];
372	      const removed = [];
373	      for (const pid of Object.keys(currMap)) {
374	        if (!prevMap[pid]) added.push(currMap[pid]);
375	        else if (prevMap[pid].severity !== 'severe' && currMap[pid].severity === 'severe') {
376	          upgraded.push(currMap[pid]);
377	        }
378	      }
379	      for (const pid of Object.keys(prevMap)) {
380	        if (!currMap[pid]) removed.push(Object.assign({ productId: pid }, prevMap[pid]));
381	      }
382	      const storeDiff = added.length + upgraded.length + removed.length;
383	      if (storeDiff) anyDiff = true;
384	
385	      lines.push('**🏬 ' + name + '**' + (stale ? ' ⚠️数据超过2小时未更新' : ''));
386	      lines.push(
387	        '在售 **' + fmtNum(L.onSale) + '**'
388	        + ' · 待关注 **' + fmtNum(L.trafficWatch) + '**'
389	        + ' · 下降 **' + fmtNum(L.trafficDecline) + '**'
390	        + ' · 限流池 **' + pool.length + '**'
391	        + '（严重 ' + pool.filter((p) => p.severity === 'severe').length
392	        + ' / 一般 ' + pool.filter((p) => p.severity !== 'severe').length + '）'
393	      );
394	      // 差异段（相对上一固定时点）
395	      if (!Object.keys(prevMap).length) {
396	        lines.push('_本时点建立限流基准 ' + pool.length + ' 条，不报差异_');
397	      } else if (!storeDiff) {
398	        lines.push('_限流无变化_');
399	      } else {
400	        if (added.length) {
401	          lines.push('新增限流 **' + added.length + '**：');
402	          lines.push(...itemLines(added, added.length));
403	          for (const it of added) allDiffItems.push({ store: name, item: it, change: 'added' });
404	        }
405	        if (upgraded.length) {
406	          lines.push('升级为严重 **' + upgraded.length + '**：');
407	          lines.push(...itemLines(upgraded, upgraded.length));
408	          for (const it of upgraded) allDiffItems.push({ store: name, item: it, change: 'upgraded' });
409	        }
410	        if (removed.length) {
411	          lines.push('解除/不再见 **' + removed.length + '**：');
412	          for (const it of removed.slice(0, 8)) {
413	            const nm = String(it.name || it.productId || '').replace(/[[\]]/g, '').slice(0, 28);
414	            // 解除项尽量保留可点开的历史编辑链（便于复查）
415	            if (it.productId) {
416	              lines.push('• ~~[' + nm + '](' + editLink(it.productId) + ')~~  SKC ' + (it.skc || '-'));
417	            } else {
418	              lines.push('• ~~' + nm + '~~  SKC ' + (it.skc || '-'));
419	            }
420	          }
421	          if (removed.length > 8) lines.push('_…另有 ' + (removed.length - 8) + ' 条_');
422	        }
423	      }
424	      // 当前仍在限流池的商品：始终列出可点链接（无变化/建基准时以前只写数字）
425	      if (pool.length) {
426	        const severeN = pool.filter((p) => p.severity === 'severe').length;
427	        const generalN = pool.length - severeN;
428	        lines.push('**当前限流 ' + pool.length + '**（严重 ' + severeN + ' / 一般 ' + generalN + '）：');
429	        // 最多列 12 条，避免卡片过长；chip 更大时提示
430	        const show = pool.slice(0, 12);
431	        lines.push(...itemLines(show, pool.length));
432	        if (pool.length > 12) {
433	          lines.push('_…另有 ' + (pool.length - 12) + ' 条未列出；打开 goods/list「商品流量待关注」可看全_');
434	        }
435	      } else if (typeof L.trafficWatch === 'number' && L.trafficWatch > 0) {
436	        lines.push('_待关注 chip=' + L.trafficWatch + ' 但本页未扫到在售限流明细（请打开该店 goods/list 或点轮巡）_');
437	      }
438	      lines.push('上次检查：' + (L.ts ? new Date(L.ts).toLocaleString('zh-CN') : '—'));
439	      lines.push('');
440	
441	      // 写回 slotTrafficMap（走串行队列，避免盖掉即时告警的 alertedTrafficIds）
442	      await updateStoreSnapshot(name, { slotTrafficMap: currMap, slotTrafficMapTs: Date.now() });
443	    }
444	  }
445	
446	  const lastCycle = (await chrome.storage.local.get('lastCycle')).lastCycle;
447	  if (lastCycle && lastCycle.ts) {
448	    lines.push('上次轮巡：' + new Date(lastCycle.ts).toLocaleString('zh-CN'));
449	  }
450	  lines.push('_汇报时间：' + new Date().toLocaleString('zh-CN') + '_');
451	
452	  // 有差异用橙/红，无差异用蓝存活
453	  const hasSevereDiff = allDiffItems.some((d) => d.item && d.item.severity === 'severe');
454	  const template = anyDiff ? (hasSevereDiff ? 'red' : 'orange') : 'blue';
455	  const title = anyDiff
456	    ? ('🔔 Temu 限流定点汇总' + (slot ? ' · ' + slot : ''))
457	    : ('📋 Temu 监测定时汇报' + (slot ? ' · ' + slot : ''));
458	  const r = await sendFeishu(cfg.webhook, title, lines, template);
459	
460	  // 差异条目同步多维表 + 严重任务
461	  if (anyDiff && typeof FeishuApp !== 'undefined') {
